<script setup lang="ts">
import { RefreshCw, Wifi } from "lucide-vue-next";
import PaginationControl from "../components/PaginationControl.vue";
import { useAdminData } from "../useAdminData";
const { logs, loading, pagination, changePage, formatTime } = useAdminData();
</script>
<template><section class="data-section monitoring-section"><div class="section-header"><div><h2>心跳与运行日志</h2><p>心跳由服务端每次接收时记录；超过 150 秒未上报的设备显示为离线</p></div><span>{{ logs.length }} 条 / 共 {{ pagination.logs.total }} 条</span></div><div v-if="loading" class="loading-state"><RefreshCw :size="20" class="spinning" aria-hidden="true" /><span>正在读取运行日志</span></div><div v-else-if="!logs.length" class="empty-state"><Wifi :size="28" aria-hidden="true" /><strong>暂无运行日志</strong><span>插件连接服务端后，心跳和任务事件会出现在这里。</span></div><div v-else class="table-scroll"><table><thead><tr><th>时间</th><th>级别</th><th>事件</th><th>设备</th><th>消息</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td>{{ formatTime(log.occurred_at) }}</td><td><span class="status" :data-status="log.level === 'error' ? 'failed' : log.level === 'warn' ? 'paused' : 'active'">{{ log.level }}</span></td><td class="mono-cell">{{ log.event }}</td><td class="mono-cell">{{ log.device_id }}</td><td>{{ log.message }}</td></tr></tbody></table></div><PaginationControl v-if="logs.length" :page="pagination.logs.page" :total-pages="pagination.logs.total_pages" :total="pagination.logs.total" item-label="条日志" @change="changePage('logs', $event)" /></section></template>
